fun main() = runBlocking {
    val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    val handler = CoroutineExceptionHandler { _, e -> println("поймал: ${e.message}") }

    scope.launch(handler) { throw RuntimeException("упал") }
    val alive = scope.launch { delay(100); println("выжил") }

    alive.join()
    println("конец")
}

