data class Box(var value: Int)

fun main() {
    val box = Box(1)

    val fromLet = box.let { it.value + 1 }
    val fromRun = box.run { value + 10 }
    val fromApply = box.apply { value = 100 }
    val fromAlso = box.also { it.value += 1 }

    println(fromLet)
    println(fromRun)
    println(fromApply)
    println(fromAlso === box)
}

