inline fun repeatTwice(action: () -> Unit) {
    action()
    action()
}

fun findFirst(numbers: List<Int>): Int? {
    numbers.forEach { n ->
        if (n > 1) return n
    }
    return null
}

fun run(): String {
    repeatTwice {
        println("шаг")
        return "вышли из run"
    }
    return "не дойдём"
}

fun main() {
    println(findFirst(listOf(1, 2, 3)))
    println(run())
}

